# model current board
cols=[37,43,49,55]; rows=[20,26,32,38,44,50,56]
valid={(55,y) for y in rows}|{(x,y) for x in cols for y in [38,44,50]}
pegs={(55,32),(37,38),(43,38),(49,38),(55,38),(43,44),(43,50),(49,50),(55,50)}
idx={p:i for i,p in enumerate(valid)}
init=sum(1<<idx[p] for p in pegs)
from functools import lru_cache
moves=[]
for x,y in valid:
 for dx,dy in [(2,0),(-2,0),(0,2),(0,-2)]:
  mid=(x+dx//2,y+dy//2); dst=(x+dx,y+dy)
  if mid in valid and dst in valid: moves.append((idx[x,y],idx[mid],idx[dst],(x,y),dst))
@lru_cache(None)
def solve(s):
 if s.bit_count()==1:return []
 for a,b,c,p,d in moves:
  if s>>a&1 and s>>b&1 and not(s>>c&1):
   ns=s^(1<<a)^(1<<b)^(1<<c)
   r=solve(ns)
   if r is not None:return [(p,d)]+r
 return None
sol=solve(init)
print(len(valid),len(pegs),sol)

